using System.ComponentModel.DataAnnotations;

namespace sv_2b4228e5993e4d6fa91993a63c47f4a0.Models;

public class AppointmentFormModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string Reason { get; set; } = string.Empty;
}

public class FutureDateAttribute : ValidationAttribute
{
    protected override ValidationResult? IsValid(object? value, ValidationContext context)
    {
        if (value is DateOnly date && date <= DateOnly.FromDateTime(DateTime.Today))
        {
            return new ValidationResult("Date must be in the future.");
        }
        return ValidationResult.Success;
    }
}

namespace sv_2b4228e5993e4d6fa91993a63c47f4a0.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Patel"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Patel"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }
        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates the patient appointment request against server-side business rules.
    /// Returns a dictionary of field-name → error-message for any violations.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(email)] = "Account has outstanding balance";
        }

        // Self-pay restriction
        if (string.Equals(insuranceProvider, "None", StringComparison.OrdinalIgnoreCase)
            && string.Equals(doctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(doctor)] = "Selected doctor does not accept self-pay patients";
        }

        // Slot race condition
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(timeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_2b4228e5993e4d6fa91993a63c47f4a0.Models
@using sv_2b4228e5993e4d6fa91993a63c47f4a0.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.TryGetValue("email", out var emailErr))
            {
                <div class="validation-message">@emailErr</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.TryGetValue("doctor", out var docErr))
                {
                    <div class="validation-message">@docErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDateChanged"
                           min="@DateOnly.FromDateTime(DateTime.Today.AddDays(1)).ToString("yyyy-MM-dd")" />
                <ValidationMessage For="() => Model.AppointmentDate" />
                @if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="validation-message">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.TryGetValue("timeSlot", out var slotErr))
                {
                    <div class="validation-message">@slotErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.Reason" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">Back</button>
            <button type="button" class="btn btn-primary me-2" @onclick="CheckAvailability" disabled="@isSubmitting">
                @(isSubmitting ? "Checking..." : "Check Availability")
            </button>

            @if (availabilityConfirmed)
            {
                <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                    Confirm Appointment
                </button>
            }
        </fieldset>
    }
</EditForm>

@if (appointmentBooked)
{
    <div class="alert alert-success mt-4" role="alert">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentFormModel Model { get; set; } = new();

    private bool showStep2;
    private bool isSubmitting;
    private bool availabilityConfirmed;
    private bool appointmentBooked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var validationMessages = new ValidationMessageStore(editContext);

        bool isValid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !Model.Email.Contains('@'))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            isValid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            isValid = false;

        if (isValid)
        {
            showStep2 = true;
            serverErrors.Clear();
            availabilityConfirmed = false;
        }
    }

    private async Task OnDoctorChanged()
    {
        serverErrors.Remove("doctor");
        availabilityConfirmed = false;
        Model.TimeSlot = string.Empty;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        availabilityConfirmed = false;
        Model.TimeSlot = string.Empty;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityConfirmed = false;

        // Client-side step 2 validation
        bool step2Valid = true;

        if (string.IsNullOrWhiteSpace(Model.Doctor))
            step2Valid = false;
        if (!Model.AppointmentDate.HasValue || Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            step2Valid = false;
        if (string.IsNullOrWhiteSpace(Model.Reason) || Model.Reason.Length > 500)
            step2Valid = false;

        if (!step2Valid)
            return;

        isSubmitting = true;

        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor,
                Model.TimeSlot);

            if (errors.Count > 0)
            {
                serverErrors = errors;
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
        availabilityConfirmed = false;
    }

    private void HandleSubmit()
    {
        if (availabilityConfirmed)
        {
            appointmentBooked = true;
        }
    }
}

